/*
 * Pro tips
 * - Numbers push; an operator replaces the top two values with their result.
 * - Pop the RIGHT operand b first, then the LEFT operand a. Compute a-b and a/b, not the reverse.
 * - Recognize the exact operator token: a negative number such as -11 is still an operand.
 * - Java integer division truncates toward zero as required. Inputs are guaranteed to be valid RPN.
 * - Check subtraction, negative division, and a single-number expression. O(t) time and O(t) space for t tokens.
 */

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Stack;

class Solution {
    public static int evalRpn(List<String> tokens) {
        Stack<Integer> stack = new Stack<>();
        for (String token : tokens) {
            if (token.equals("+")) {
                int b = stack.pop();
                int a = stack.pop();
                stack.push(a + b);
            } else if (token.equals("-")) {
                int b = stack.pop();
                int a = stack.pop();
                stack.push(a - b);
            } else if (token.equals("*")) {
                int b = stack.pop();
                int a = stack.pop();
                stack.push(a * b);
            } else if (token.equals("/")) {
                int b = stack.pop();
                int a = stack.pop();
                stack.push(a / b);
            } else {
                stack.push(Integer.parseInt(token));
            }
        }
        return stack.pop();
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        int tokensLength = Integer.parseInt(scanner.nextLine());
        List<String> tokens = new ArrayList<>();
        for (int i = 0; i < tokensLength; i++) {
            tokens.add(scanner.nextLine());
        }
        scanner.close();
        int res = evalRpn(tokens);
        System.out.println(res);
    }
}
